"""Typed Jev decisions; no code, locators or actions are generated by a model."""
import json
import math
import os
import time
import urllib.request
from pathlib import Path


class DecisionError(RuntimeError):
    pass


def load_env(root):
    path = Path(root) / '.env'
    if path.exists():
        for line in path.read_text(encoding='utf-8-sig').splitlines():
            if '=' in line and not line.lstrip().startswith('#'):
                key, value = line.split('=', 1)
                os.environ.setdefault(key.strip(), value.strip())


def validate_answer(answer, choices, cfg):
    probs = answer.get('probabilities', {})
    if answer.get('type') != 'choice' or set(probs) != set(choices):
        raise DecisionError('Jev 응답 선택지 불일치')
    if any(not isinstance(p, (int, float)) or isinstance(p, bool) or not math.isfinite(p) or not 0 <= p <= 1 for p in probs.values()):
        raise DecisionError('Jev 확률 형식 오류')
    if abs(sum(probs.values()) - 1) > .02:
        raise DecisionError('Jev 확률 합계 오류')
    ranked = sorted(probs, key=probs.get, reverse=True)
    if answer.get('choice') != ranked[0]:
        raise DecisionError('Jev 선택과 확률 불일치')
    if probs[ranked[0]] < cfg['min_probability'] or probs[ranked[0]] - probs[ranked[1]] < cfg['min_margin']:
        raise DecisionError('Jev 판단 불확실: 자동 중지')
    if ranked[0] == 'STOP':
        raise DecisionError('Jev 중지 선택')
    return ranked[0]


class DecisionEngine:
    def __init__(self, mode, cfg, log):
        self.mode, self.cfg, self.log, self.calls = mode, cfg, log, 0

    def choose(self, state, choices, instructions):
        self.calls += 1
        if self.calls > self.cfg['max_jev_calls']:
            raise DecisionError('Jev 호출 한도 초과')
        start = time.monotonic()
        if self.mode == 'live':
            key = os.getenv('JEV_API_KEY', '')
            if not key:
                raise DecisionError('JEV_API_KEY 미설정. .env를 확인하세요.')
            payload = {'model': os.getenv('JEV_MODEL', 'jev-latest'), 'state': state,
                       'questions': {'action': {'type': 'choice', 'instructions': instructions,
                                                 'criteria': choices}}}
            request = urllib.request.Request('https://api.typesafe.ai/v1/systemone',
                data=json.dumps(payload, ensure_ascii=False).encode(),
                headers={'Authorization': 'Bearer ' + key, 'Content-Type': 'application/json'})
            try:
                with urllib.request.urlopen(request, timeout=12) as response:
                    result = json.load(response)
                answer = result['answers']['action']
            except Exception as exc:
                # Never expose request headers, key or raw provider error bodies.
                raise DecisionError('Jev 호출 실패: ' + type(exc).__name__) from None
        else:
            # Explicit deterministic test double. Never represented as a Jev result.
            text = json.dumps(state, ensure_ascii=False)
            selected = 'STOP'
            if '연결 시간이 초과' in text and 'RETRY' in choices:
                selected = 'RETRY'
            elif ('처리 중' in text or '진행 중' in text) and 'WAIT' in choices:
                selected = 'WAIT'
            elif '후보' in state:
                for option, label in state['후보'].items():
                    if '생산계획' in label and ('미입고' in label or '입고 지연' in label):
                        selected = option
                        break
            answer = {'type': 'choice', 'choice': selected, 'confidence': .99,
                'probabilities': {k: .99 if k == selected else .01/(len(choices)-1) for k in choices}}
        self.log('decision', mode=self.mode, state=state, answer=answer,
                 elapsed_ms=round((time.monotonic()-start)*1000))
        return validate_answer(answer, choices, self.cfg)
